#include <iostream>
#include <string>
#include <vector>

int main() {
    // Reading an initial grade and counter offset to demonstrate sequential execution
    int grade{0};
    int total{0};
    int counter{0};

    if (std::cin >> grade) {
        // Bohm & Jacopini sequence structure: action 1 followed by action 2
        total = total + grade;   // Action 1: add grade to total
        counter = counter + 1;   // Action 2: add 1 to counter

        std::cout << "Total: " << total << "\n";
        std::cout << "Counter: " << counter << "\n";
    }
    return 0;
}

#include <iostream>

int main() {
    int grade{0};
    if (std::cin >> grade) {
        // Single-selection: if
        if (grade >= 60) {
            std::cout << "Passed\n";
        }

        // Double-selection: if...else
        if (grade >= 60) {
            std::cout << "Status: Satisfactory\n";
        } else {
            std::cout << "Status: Unsatisfactory\n";
        }
    }
    return 0;
}
